def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, 0)]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(p[0] for p in pts), max(p[0] for p in pts)
    c0, c1 = min(p[1] for p in pts), max(p[1] for p in pts)
    eight = [(r, c) for r, c, v in pts if v == 8]
    cr, cc = (r0 + r1) / 2, (c0 + c1) / 2
    ar, ac = min(eight, key=lambda p: abs(p[0]-cr) + abs(p[1]-cc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = bg
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                dr, dc = r-ar, c-ac
                for pr, pc, color in pts:
                    nr, nc = pr+dr, pc+dc
                    if 0 <= nr < h and 0 <= nc < w:
                        out[nr][nc] = color
    return out
